/*
 * Static inline accessors.
 *
 * Use these accessors instead of member chains such as
 * `node->body.rule.children.len`. Each accessor compiles to a few loads, and
 * CFFI calls them without an intermediate object for each member.
 *
 * The rule accessors are valid only for nodes with
 * `node_tag >= ANTLR_NODE_TAG_FIRST_RULE`. The leaf accessor is valid only
 * for other nodes.
 */

static inline bool antlr_node_is_rule(const AntlrTreeNode *node) {
  return node->node_tag >= ANTLR_NODE_TAG_FIRST_RULE;
}

static inline const AntlrToken *antlr_rule_start(const AntlrTreeNode *node) {
  return node->body.rule.start;
}

static inline const AntlrToken *antlr_rule_stop(const AntlrTreeNode *node) {
  return node->body.rule.stop;
}

static inline const AntlrTreeNode *antlr_rule_parent(const AntlrTreeNode *node) {
  return node->body.rule.parent;
}

static inline uint32_t antlr_rule_child_count(const AntlrTreeNode *node) {
  return node->body.rule.children.len;
}

/* The array of the `antlr_rule_child_count(node)` children of `node`. */
static inline const AntlrTreeNode *const *antlr_rule_children(const AntlrTreeNode *node) {
  const AntlrNodeChildren *children = &node->body.rule.children;
  return children->cap == 0 ? children->storage.inline_slots : children->storage.spilled;
}

/* The child at `index`, which must be less than `antlr_rule_child_count(node)`. */
static inline const AntlrTreeNode *antlr_rule_child(const AntlrTreeNode *node, uint32_t index) {
  return antlr_rule_children(node)[index];
}

static inline const AntlrToken *antlr_leaf_symbol(const AntlrTreeNode *node) {
  return node->body.leaf.symbol;
}

static inline int32_t antlr_token_type(const AntlrToken *token) {
  int32_t type = token->type_and_channel & ((INT32_C(1) << ANTLR_TOKEN_TYPE_BITS) - 1);
  return type >= (INT32_C(1) << (ANTLR_TOKEN_TYPE_BITS - 1))
      ? type - (INT32_C(1) << ANTLR_TOKEN_TYPE_BITS)
      : type;
}

static inline int32_t antlr_token_channel(const AntlrToken *token) {
  int32_t value = token->type_and_channel;
  /* An arithmetic shift without implementation-defined behavior. */
  return value >= 0 ? value >> ANTLR_TOKEN_TYPE_BITS
                    : -1 - ((-1 - value) >> ANTLR_TOKEN_TYPE_BITS);
}

